  CAST(DATE_TRUNC('MONTH', q_line.order_date) AS DATE) AS ordered_month,
  CAST(DATE_TRUNC('QUARTER', q_line.order_date) AS DATE) AS ordered_quarter,
  CAST(DATE_TRUNC('WEEK', q_line.order_date) AS DATE) AS ordered_week,
  CAST(DATE_TRUNC('YEAR', q_line.order_date) AS DATE) AS ordered_year,
  q_line.status AS status
